solution.sanitized:
def decimal_octets(text):
    parts = text.split(".")
    if len(parts) != 4 or any(not p or any(c not in "0123456789" for c in p) for p in parts):
        raise ValueError("invalid address")
    values = tuple(map(int, parts))
    if any(v > 255 for v in values):
        raise ValueError("invalid address")
    return values

